"""Parity of api/app/textnorm.py with PostgreSQL (fixtures generated by scripts/gen_fnorm_table.py).

Run: python -m pytest tests/test_textnorm.py   or   python tests/test_textnorm.py
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "api"))

from app.textnorm import contains, f_norm, like, startswith  # noqa: E402

FIX = json.loads((ROOT / "tests" / "fixtures" / "fnorm.json").read_text(encoding="utf-8"))


def test_fnorm_parity():
    bad = [(x, pg, f_norm(x)) for x, pg in FIX["pairs"] if f_norm(x) != pg]
    assert len(FIX["pairs"]) >= 3000
    assert not bad, f"{len(bad)} mismatches, e.g. {bad[:5]!r}"


def test_fnorm_tricky():
    assert f_norm(None) is None
    assert f_norm("") == ""
    assert f_norm("İ") == "i"
    assert f_norm("ǅ") == "dz"
    assert f_norm("ﬃ") == "ffi"
    assert f_norm("Straße") == "strasse"
    assert f_norm("Æ") == "ae"
    assert f_norm("É") == "e"
    assert f_norm("é") == "e"          # combining acute is removed by unaccent.rules
    assert f_norm("Poción ÑANDÚ") == "pocion nandu"


def test_like_parity():
    bad = [(v, p, pg, like(v, p)) for v, p, pg in FIX["like"] if like(v, p) != pg]
    assert not bad, f"{len(bad)} mismatches, e.g. {bad[:5]!r}"


def test_contains_startswith_match_like():
    for v, p, pg in FIX["like"]:
        if p.startswith("%") and p.endswith("%") and len(p) >= 2:
            needle = p[1:-1]
            assert contains(v, needle) == like(v, "%" + needle + "%")
        if p.endswith("%"):
            assert startswith(v, p[:-1]) == like(v, p)
    assert like(None, "%") is None and contains("a", None) is None and startswith(None, "a") is None


if __name__ == "__main__":
    tests = [(n, f) for n, f in sorted(globals().items()) if n.startswith("test_") and callable(f)]
    for name, fn in tests:
        fn()
        print("ok  ", name)
    print(f"{len(tests)} passed ({len(FIX['pairs'])} f_norm pairs, {len(FIX['like'])} LIKE cases)")
